class ADMIN19B(object):
    """

    """
    _api_client = None

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        self._api_client = api_client

    def __del__(self):
        self.disconnect()

    def disconnect(self):
        """
        Disconnect api client.

        TODO: Catch teardown errors
        """
        if self._api_client is not None:
            self._api_client.teardown()

    def get_bts_info(self, timeout=10):
        """
        Get overall information regarding Node B from M-Plane (OAM).

        :param int timeout: Timeout for the operation.
        :return dict: Dictionary structure with data, where Keys are various information categories.
                      More details (content of requestMessage is returned data):
                      https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getBtsInformation.html
        """
        result = self._api_client.execute_customer_procedure("getBtsInformation", {}, timeout)
        return result.get(ProvidedContent.request_message)

    def get_detected_hw_info(self, timeout=10):
        """
        Get detected hardware information from M-Plane (OAM).
        See: ProvidedContent.detectable_hardware.

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If any of supported hardware categories have not been provided by M-Plane.
        :return dict: Dictionary structure where Keys are various hardware categories
                      listed in ProvidedContent.detectable_hardware, and Values are lists containing information about
                      each detected element provided by M-Plane.

        Example

        ::

            {
            "cabinets": [
             {
                "id": {
                   "internal": "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/EQM_R-4/APEQM_R-1/CABINET_R-1",
                   "configuration": "MRBTS-1/EQM-1/APEQM-1/CABINET-1",
                   "runtime": "MRBTS-1/EQM_R-4/APEQM_R-1/CABINET_R-1"
                },
                "release": 4,
                "productCode": "473098A",
                "productName": null
             }
            ],
            'systemModules': [{u'cabinetId': {u'configuration': u'MRBTS-10191/EQM-1/APEQM-1/CABINET-1',
                       u'internal': u'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/
                       CABINET_R-1',
                       u'runtime': u'MRBTS-10191/EQM_R-1/APEQM_R-1/CABINET_R-1'},
            u'id': {u'configuration': u'MRBTS-10191/EQM-1/APEQM-1/CABINET-1/SMOD-1',
                u'internal': u'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/
                SMOD_R-1',
                u'runtime': u'MRBTS-10191/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1'},
            u'moduleLocation': None,
            u'ports': [{u'id': {u'internal': u'/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/CABINET_L-1/SMOD_L-1/
            CONNECTOR_L-3'},
                    u'label': u'EIF1'},
                   {u'id': {u'internal': u'/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/CABINET_L-1/SMOD_L-1/
                   CONNECTOR_L-2'},
                    u'label': u'EIF2'},
                   {u'id': {u'internal': u'/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/CABINET_L-1/SMOD_L-1/
                   CONNECTOR_L-1'},
                    u'label': u'LMP'}],
            u'productCode': u'474021A',
            u'productName': u'ASIK AirScale Common',
            u'serialNumber': u'L1182214824',
            u'status': {u'administrativeState': u'Unlocked',
                    u'availabilityStatus': u'Failed',
                    u'operationalState': u'Disabled',
                    u'usageState': u'Idle'}}],
            'transportModules': []}

             }
        """
        detected_hw_data = {}
        bts_info = self.get_bts_info(timeout=timeout)

        for hw_element in ProvidedContent.detectable_hardware:
            hw_element_data = bts_info.get(hw_element)

            if hw_element_data is None:
                error_desc = "Hardware component data for {} has not been provided by M-Plane."
                raise DataNotAvailable(error_desc.format(hw_element))

            detected_hw_data[hw_element] = hw_element_data

        return detected_hw_data

