    def get_fan_info(self, fan_location='RMOD', timeout=10):
        """
        Get fan statuses information from M-Plane (OAM).

        :param fan_location: RMOD is default value
        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If module data is not provided by M-Plane.
        :return dict: Dict where key is module internal id shortened eg. 'RMOD_R-3', value is fanStatus dict.

        Example

        ::

            {
            'RMOD_R-1':
                {
                'availabilityStatus': 'Online',
                'operationalState': 'Enabled',
                'usageState': 'Idle'
                }
            }
        """
        logging.warning('[DEPRACATION WARNING] This keyword is depracated. Use get_rmod_fan_info or '
                        'get_cabinets_fan_info instead.')
        if fan_location in ProvidedContent.fan_status_locations:
            status_locations = ProvidedContent.fan_status_locations[fan_location]

        else:
            msg = 'Incorrect parameter: {}. Should be `RMOD`.'.format(fan_location)
            raise IncorrectParameterValue(msg)

        bts_info = self.get_bts_info(timeout=timeout)

        try:
            for status_location in status_locations:
                bts_info = bts_info[status_location]
            modules_data = bts_info
        except (AttributeError, KeyError):
            raise DataNotAvailable("information has not been provided by M-Plane.")

        fan_info = self.__get_info_for_modules(modules_data, 'fanStatus')

        return fan_info

