    def _save_content_to_file(self, content, full_path):
        with open(full_path, 'w') as target_file:
            target_file.write(content)

    def get_current_scf_file(self, local_dir_path, file_name, timeout=10):
        """
        Save a current SCF to a file and get a path to this file.

        :param str local_dir_path: Path to directory to store final SCF.
        :param str file_name: File name of final SCF.
        :param int timeout: Timeout for the operation.
        :return str: Path to the file with current SCF content.
        """
        content = self.get_current_scf_content(timeout=timeout)
        full_path = path.join(local_dir_path, file_name)
        self._save_content_to_file(content, full_path)
        return full_path

    def get_current_scf_content(self, timeout=10):
        """
        Get a current content of SCF.

        :param int timeout: Timeout for the operation.
        :return str: Current content of SCF.
        """
        content = self._api_client.execute_procedure("generateScf", {}, timeout)
        if content is None:
            raise DataNotAvailable("SCF content has not been provided by M-Plane.")
        return base64.b64decode(content).decode('utf-8')

