    def get_smod_role(self, timeout=10):
        """
        Get SMOD active role.

        :param int timeout: Timeout for the operation.
        :raises DataNotAvailable: If keyword is run on a single-core testing environment.

        :return dict: dict of SMOD active roles.

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getSmodPosition.html
        """
        reply = self._api_client.execute_infomodel_request("getSmodPosition", {}, timeout)
        if isinstance(reply, dict):
            if len(reply) > 1:
                for module_name, smod in reply.items():
                    reply[module_name] = search_recursively(smod[0], 'activeRole')
            else:
                msg = 'Cannot get `activeRole` parameter for single system module configuration'
                raise DataNotAvailable(msg)
        return reply

