    def start_5g_uplink_test(self, dist_name, frc_index, beam_pattern_id,
                             interval, prb_offset, ru_mode, phys_cell_id,
                             nrarfcn_ul=None, timeout=60):
        """
        Starts 5G Uplink Test.

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param str frc_index: One of the following: `G_FR1_A1_1`, `G_FR1_A1_2`,
                                `G_FR1_A1_4`, `G_FR1_A1_5`, `G_FR1_A1_7`, `G_FR1_A2_1`,
                                `G_FR1_A2_4`, `G_FR1_A2_5`, `GFR2_A1_2`, `G_FR2_A1_3`.
        :param int beam_pattern_id: [0..1200]
        :param int interval: Reporting time interval [1..3600]
        :param int prb_offset: [0..273]
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int nrarfcn_ul: (Optional) [0..3279165]
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
                }
            },

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-start5GUplinkTest.html

        """
        beam_pattern_id = int(beam_pattern_id)
        interval = int(interval)

        params_to_check = {'frc_index': frc_index, 'beam_pattern_id': beam_pattern_id, 'interval': interval,
                           'prb_offset': prb_offset, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'nrarfcn_ul': nrarfcn_ul}

        self._validation_5g_uplink_parameters(params_to_check)

        parameters = {
            'nrcell_rDN': dist_name,
            'params': {
                'frcIndex': frc_index,
                'beamPatternId': beam_pattern_id,
                'reportingTimeInterval': interval,
                'prbOffset': prb_offset,
                'ruMode': ru_mode,
                'physCellId': phys_cell_id,
                'nrarfcnUl': nrarfcn_ul
            }
        }
        if parameters['params']['nrarfcnUl'] is None:
            del parameters['params']['nrarfcnUl']
        return self._api_client.execute_procedure('start5GUplinkTest',
                                                  parameters, timeout)

    def _check_parameters(self, params_to_check, params, subpage):
        for param in params_to_check:
            if params_to_check[param] is False:
                raise_value_error(param=param,
                                  value=str(params[param]),
                                  subpage=subpage)

    def _validation_5g_uplink_parameters(self, params):
        frc_index = (params['frc_index'] in ("G_FR1_A1_1", "G_FR1_A1_2", "G_FR1_A1_4",
                                             "G_FR1_A1_5", "G_FR1_A1_7", "G_FR1_A2_1",
                                             "G_FR1_A2_4", "G_FR1_A2_5", "GFR2_A1_2",
                                             "G_FR2_A1_3"))
        beam_pattern_id = (0 <= params['beam_pattern_id'] <= 1200)
        interval = (1 <= params['interval'] <= 3600)
        prb_offset = (0 <= params['prb_offset'] <= 273)
        ru_mode = (params['ru_mode'] in ("NR_Only", "MSR"))
        phys_cell_id = (0 <= params['phys_cell_id'] <= 1007)
        nrarfcn_ul = (params['nrarfcn_ul'] is None or (0 <= params['nrarfcn_ul'] <= 3279165))

        params_to_check = {'frc_index': frc_index, 'beam_pattern_id': beam_pattern_id, 'interval': interval,
                           'prb_offset': prb_offset, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'nrarfcn_ul': nrarfcn_ul}

        self._check_parameters(params_to_check, params, "tutorial-start5GUplinkTest.html")

